import*as THREE from'three';import{materials}from'../../core/index.js';import{addCadParts}from'../../modeling/cad.js';import{mesh,slab,screw}from'../../modeling/parts.js';import data from'./geometry-data.js';import{grove,terminal}from'./connectors.js';import{addStickers}from'./stickers.js';
const tau=Math.PI*2;function hole(s,x,y,r){const p=new THREE.Path();p.absarc(x,y,r,0,tau,false);s.holes.push(p);}function extrude(parent,s,depth,p,m,n){return mesh(parent,new THREE.ExtrudeGeometry(s,{depth,bevelEnabled:false,curveSegments:48}),m,p,n);}
function board(host){const s=new THREE.Shape();s.moveTo(-10.4,-24);s.lineTo(-8.8,-26);s.lineTo(-5.5,-26);s.lineTo(-5.5,-20.2);s.lineTo(5.5,-20.2);s.lineTo(5.5,-26);s.lineTo(8.8,-26);s.lineTo(10.4,-24);s.lineTo(10.4,-19.6);s.lineTo(8,-19.6);s.absarc(8,-16,3.6,-Math.PI/2,-Math.PI*1.5,true);s.lineTo(10.4,-12.4);s.lineTo(10.4,24.3);s.lineTo(8.5,26.3);s.lineTo(-8.5,26.3);s.lineTo(-10.4,24.3);s.lineTo(-10.4,-12.4);s.lineTo(-8,-12.4);s.absarc(-8,-16,3.6,Math.PI/2,-Math.PI/2,true);s.lineTo(-10.4,-19.6);s.closePath();hole(s,0,-16,2.1);const pcb=extrude(host.body,s,.8,[0,0,-2.5],materials.plastic(0x148251,{roughness:.86}),'AC Measure fixed PCB with actual mounting reliefs and central retaining bore');pcb.userData.role='physical-pcb';const metal=materials.metal(0xb6bba9,{roughness:.49}),dark=materials.plastic(0x21241f,{roughness:.86}),ceramic=materials.plastic(0xaaa07b,{roughness:.86}),packages=[];
 const ic=(x,y,w,h,z,depth,n,leads)=>{const body=slab(host.body,w,h,depth,.13,[x,y,z],dark,[],.02);body.name='AC Measure '+n;packages.push(body);for(const sign of[-1,1])for(let i=0;i<leads;i++)mesh(host.body,new THREE.BoxGeometry(.9,.3,.18),metal,[x+sign*(w/2+.3),y+(i-(leads-1)/2)*.65,-1.45],n+' physical lead');return body;};const mcu=ic(4.3,-5.4,5.4,6.4,-1.5,1.2,'U4 STM32G030F6P6 fixed package',10),meter=ic(-4.6,7.5,4.2,5.1,-1.5,1.5,'IC2 HLW8032 fixed package',4),converter=ic(2.3,4.2,10.3,7.7,-1.5,3.7,'U2 B0505ST16-W5 isolated supply physical package',7),opto=ic(-6.6,-3.3,4.0,4.2,-1.5,2.2,'IC1 EL357NB optocoupler physical package',2),regulator=ic(-2.1,-7.2,2.8,3.4,-1.5,1,'U3 HX6306 regulator fixed package',2),fuse=ic(-3.9,17,5.7,8.1,-1.5,3.6,'FUSE1 TBT10A250V fixed fuse body',1);
 const shunt=mesh(host.body,new THREE.BoxGeometry(3.2,6.4,.55),dark,[6.6,19.2,-1.2],'AC Measure fixed MA251230 current shunt body');for(const sign of[-1,1])mesh(host.body,new THREE.BoxGeometry(3.2,1.15,.65),metal,[6.6,19.2+sign*2.7,-1.2],'AC Measure shunt metal termination');
 const passives=[];for(const[i,x,y]of[[1,-8.7,23],[2,-8.7,20.6],[3,-8.7,18.2],[4,-8.7,15.8],[5,8.5,13.6],[6,7.5,10.8],[7,-7.9,1.4],[8,-4.5,-8],[9,.5,-10.7],[10,3.2,-10.7],[11,6.3,-10.7],[12,8.2,-22.3]]){passives.push(mesh(host.body,new THREE.BoxGeometry(1.6,.9,.7),i<5?dark:ceramic,[x,y,-1.3],'AC Measure fixed capacitor resistor package '+i));for(const sign of[-1,1])mesh(host.body,new THREE.BoxGeometry(.28,.9,.72),metal,[x+sign*.66,y,-1.3],'AC Measure passive solder end');}
 const pads=[];for(let i=0;i<5;i++){const shape=new THREE.Shape();shape.absarc(0,0,.48,0,tau,false);pads.push(extrude(host.body,shape,.035,[-7.3+i*1.7,-10.6,-1.69],materials.metal(0xc6a947,{roughness:.51}),'AC Measure concealed J1 SWD pad '+(i+1)));}
 const ledBase=mesh(host.body,new THREE.BoxGeometry(1.6,.85,.45),materials.plastic(0xe4e5d8,{roughness:.72}),[8.3,-20.9,-1.5],'AC Measure concealed D1 red LED substrate'),hiddenLed=mesh(host.body,new THREE.BoxGeometry(.9,.65,.16),materials.plastic(0xa73c36,{roughness:.45}),[8.3,-20.9,-1.195],'AC Measure concealed red D1 resin,non-emissive');for(const sign of[-1,1])mesh(host.body,new THREE.BoxGeometry(.2,.85,.35),metal,[8.3+sign*.7,-20.9,-1.57],'AC Measure concealed D1 solder end');return{pcb,mcu,meter,converter,opto,regulator,fuse,shunt,packages,passives,pads,ledBase,hiddenLed};}
export function buildACMeasure(host){const parts=addCadParts(host,data,{shell:materials.plastic(0xe9eae5,{roughness:.78})}),pcb=board(host),input=grove(host),output=terminal(host),fixing=screw(host.body,[0,-16,-3.01],'back',1.55);fixing.name='AC Measure fixed recessed rear hex screw';fixing.traverse(o=>{if(o.isMesh)o.name='AC Measure fixed hex retaining screw face';});mesh(host.body,new THREE.CylinderGeometry(.65,.65,4.1,32).rotateX(Math.PI/2),materials.metal(0x9ca093),[0,-16,-.9],'AC Measure concealed fixed screw shank');const frontCarrier=slab(host.body,16,26.5,.045,.9,[0,2.75,3.805],materials.plastic(0xd9dadb,{roughness:.86}),[],.005);frontCarrier.name='AC Measure physical front adhesive label substrate over native printed recess';const backCarrier=slab(host.body,16,36,.045,.02,[0,6,-3.85],materials.plastic(0xd9dadb,{roughness:.86}),[],.005);backCarrier.name='AC Measure physical rear adhesive label substrate over native printed recess';host.acMeasureAssembly={parts,pcb,input,output,fixing,frontCarrier,backCarrier};host.unitStickers=addStickers(host);}
